CONTEXT_FOLDER_PATH = "Shared/uipath-maestro-flow/BillingDispute"

context_res_uuid = str(uuid.uuid4())

reg_autonomous = json.load(open("/tmp/reg_autonomous.json"))["Data"]["Node"]
reg_end = json.load(open("/tmp/reg_end.json"))["Data"]["Node"]
