flow = json.load(open(os.path.join(FLOW_DIR, "BillingDisputeAnalyst.flow")))
trigger_def = flow["definitions"][0]
start_layout = flow["layout"]["nodes"]["start"]

flow["variables"] = {
    "globals": [
        {"id": "disputeDescription", "direction": "in", "type": "string", "triggerNodeId": "start"},
        {"id": "invoiceNumber", "direction": "in", "type": "string", "triggerNodeId": "start"},
        {"id": "determination", "direction": "out", "type": "string"},
        {"id": "rationale", "direction": "out", "type": "string"}
    ],
    "nodes": [
        {"id": "billingDisputeAnalyst1", "binding": {"nodeId": "billingDisputeAnalyst1", "outputId": "output"}},
        {"id": "billingDisputeAnalyst1-error", "binding": {"nodeId": "billingDisputeAnalyst1", "outputId": "error"}}
    ]
}

flow["nodes"] = [
    flow["nodes"][0],
    {
        "id": "billingDisputeAnalyst1",
        "type": "uipath.agent.autonomous",
        "typeVersion": reg_autonomous["version"],
        "display": {"label": "Billing Dispute Analyst"},
        "inputs": {
            "systemPrompt": "Analyze billing disputes grounded on SOP knowledge.",
            "userPrompt": "Analyze the billing dispute and provide determination and rationale.",
            "source": AGENT_PROJECT_ID,
            "agentInputVariables": [
                {"id": "start__output__disputeDescription", "type": "string", "binding": "=$vars.start.output.disputeDescription", "description": "Bound from $vars.start.output.disputeDescription"},
                {"id": "start__output__invoiceNumber", "type": "string", "binding": "=$vars.start.output.invoiceNumber", "description": "Bound from $vars.start.output.invoiceNumber"}
            ],
            "agentOutputVariables": [
                {"id": "determination", "type": "string"},
                {"id": "rationale", "type": "string"}
            ]
        },
        "outputs": {
            "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
            "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    {
        "id": "billingDisputeContextIndex1",
        "type": CONTEXT_INDEX_NODE_TYPE,
        "typeVersion": reg_context["version"],
        "display": {"label": CONTEXT_INDEX_NAME},
        "inputs": {"source": context_res_uuid}
    },
    {
        "id": "end1",
        "type": "core.control.end",
        "typeVersion": reg_end["version"],
        "display": {"label": "End"},
        "outputs": {
            "determination": {"source": "=js:$vars.billingDisputeAnalyst1.output.determination"},
